begin;
\ir bag-reception-fixture.inc
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values ('f0000000-0000-4000-8000-000000000221','bulk-life@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000221","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Bulk lifecycle','bulk-lifecycle',gen_random_uuid())::text,true);
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic seller','seller@bulk.test','')::text,true);
select set_config('test.agreement',publish_seller_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'Synthetic terms','Test','en',false)::text,true);
select record_agreement_evidence(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,current_setting('test.agreement')::uuid,'Signed');
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),null,(current_store_policy(current_setting('test.tenant')::uuid)->'policy') || '{"vatModeConsignmentPrivate":"consignment_margin","vatModeStoreOwned":"store_full"}');
select set_config('test.bag',receive_bag_with_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,'',current_setting('test.agreement')::uuid)::text,true);
create function pg_temp.make_item() returns uuid language plpgsql as $$
declare draft uuid:=gen_random_uuid(); item uuid:=gen_random_uuid();
begin
 perform pg_temp.prepare_bag_reception(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.bag')::uuid,draft,0,'Synthetic bulk jacket','Jackets','Good');
 perform public.accept_item(current_setting('test.tenant')::uuid,item,'reception_review',draft,1,20000);
 return item;
end $$;
select set_config('test.first',pg_temp.make_item()::text,true);
select set_config('test.second',pg_temp.make_item()::text,true);
select set_config('test.third',pg_temp.make_item()::text,true);
select end_sale_period(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.second')::uuid,'return');
select set_config('test.operation','{"kind":"setPrice","priceOre":15000,"reason":"Synthetic price correction"}',true);
select set_config('test.preview',preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array[current_setting('test.first')::uuid,current_setting('test.second')::uuid,current_setting('test.third')::uuid],current_setting('test.operation')::jsonb)::text,true);
select is(jsonb_array_length(current_setting('test.preview')::jsonb),3,'preview retains every selected item');
select is(current_setting('test.preview')::jsonb->1->>'reason','ended','ended item explains skip');
select is((current_setting('test.preview')::jsonb->0->>'priceOre')::bigint,15000::bigint,'preview uses exact proposed price');
select set_item_price(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.third')::uuid,19000,'Concurrent change');
select set_config('test.request',gen_random_uuid()::text,true);
select set_config('test.result',apply_item_lifecycle_batch(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,current_setting('test.operation')::jsonb,current_setting('test.preview')::jsonb)::text,true);
select is(current_setting('test.result')::jsonb->'items'->0->>'status','applied','eligible item applied');
select is(current_setting('test.result')::jsonb->'items'->1->>'reason','ended','ended item skipped');
select is(current_setting('test.result')::jsonb->'items'->2->>'reason','changed','concurrently changed item skipped');
select is(apply_item_lifecycle_batch(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,current_setting('test.operation')::jsonb,current_setting('test.preview')::jsonb),current_setting('test.result')::jsonb,'exact retry includes original skipped results');
select is((select count(*) from item_events where item_id=current_setting('test.first')::uuid and kind='price_set' and detail->>'reason'='Synthetic price correction'),1::bigint,'one price event after retry');
select throws_like($$select apply_item_lifecycle_batch(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,'{"kind":"setPrice","priceOre":16000,"reason":"Different"}',current_setting('test.preview')::jsonb)$$,'%REQUEST_CONFLICT%','request identity binds full input');
select throws_like($$select preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array[current_setting('test.first')::uuid,current_setting('test.first')::uuid],current_setting('test.operation')::jsonb)$$,'%INVALID_INPUT%','duplicate items rejected');
select throws_like($$select preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,'{}'::uuid[],current_setting('test.operation')::jsonb)$$,'%INVALID_INPUT%','empty selection rejected');
select is(preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array[gen_random_uuid()],current_setting('test.operation')::jsonb)->0->>'reason','missing','unknown item has no leaked facts');
select is(preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array[current_setting('test.first')::uuid],'{"kind":"end","endAction":"recycle","reason":""}')->0->>'reason','collection_not_due','recycling respects collection deadline');
select is(preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array[current_setting('test.first')::uuid],'{"kind":"markdown"}')->0->>'reason','markdown_not_due','only due markdown can apply');
select set_config('test.operation','{"kind":"extend","days":10,"reason":"Synthetic extension"}',true);
select set_config('test.preview',preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array[current_setting('test.first')::uuid],current_setting('test.operation')::jsonb)::text,true);
select lives_ok($$select apply_item_lifecycle_batch(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.operation')::jsonb,current_setting('test.preview')::jsonb)$$,'extension delegates to existing engine');
select is((select (detail->>'days')::integer from item_events where item_id=current_setting('test.first')::uuid and kind='period_extended'),10,'one extension with selected days');
select set_config('test.skip',preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array[current_setting('test.second')::uuid],current_setting('test.operation')::jsonb)::text,true);
select reopen_item_period(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.second')::uuid,(select id from item_events where item_id=current_setting('test.second')::uuid and kind='period_ended'),(now() at time zone 'Europe/Stockholm')::date+14,'Synthetic reopening');
select is(apply_item_lifecycle_batch(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.operation')::jsonb,current_setting('test.skip')::jsonb)->'items'->0->>'reason','ended','item excluded in preview remains excluded even after reopening');
select throws_like($$select preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array(select gen_random_uuid() from generate_series(1,51)),current_setting('test.operation')::jsonb)$$,'%INVALID_INPUT%','batch capped at fifty');
select throws_like($$select preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array[current_setting('test.first')::uuid],'{"kind":"setPrice","priceOre":1.5,"reason":"Test"}')$$,'%INVALID_INPUT%','fractional ore rejected in database');
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),(current_store_policy(current_setting('test.tenant')::uuid)->>'id')::uuid,(current_store_policy(current_setting('test.tenant')::uuid)->'policy') || '{"markdownSteps":[{"afterDays":0,"percent":10}]}');
select set_config('test.markdown',pg_temp.make_item()::text,true);
select set_config('test.markdown_preview',preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array[current_setting('test.markdown')::uuid],'{"kind":"markdown"}')::text,true);
select is((current_setting('test.markdown_preview')::jsonb->0->>'priceOre')::bigint,18000::bigint,'due markdown preview uses accepted-price arithmetic');
select lives_ok($$select apply_item_lifecycle_batch(current_setting('test.tenant')::uuid,gen_random_uuid(),'{"kind":"markdown"}',current_setting('test.markdown_preview')::jsonb)$$,'bulk markdown applies due step');
select is((select (detail->>'priceOre')::bigint from item_events where item_id=current_setting('test.markdown')::uuid and kind='markdown_applied'),18000::bigint,'markdown stores the previewed exact price');
reset role;
insert into auth.users(id,email,email_confirmed_at) values ('f0000000-0000-4000-8000-000000000222','bulk-reader@example.test',now());
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.tenant')::uuid,'f0000000-0000-4000-8000-000000000222','readonly');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000222","role":"authenticated"}';
select throws_ok($$select preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array[current_setting('test.first')::uuid],current_setting('test.operation')::jsonb)$$,'42501','FORBIDDEN','readonly cannot preview actions');
select throws_ok($$select apply_item_lifecycle_batch(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.operation')::jsonb,current_setting('test.preview')::jsonb)$$,'42501','FORBIDDEN','readonly cannot apply');
select throws_ok($$select preview_item_lifecycle_batch(gen_random_uuid(),array[current_setting('test.first')::uuid],current_setting('test.operation')::jsonb)$$,'42501','FORBIDDEN','foreign tenant denied before reading items');
reset role;
update tenant_members set role='staff' where tenant_id=current_setting('test.tenant')::uuid and user_id='f0000000-0000-4000-8000-000000000222';
set local role authenticated;
select set_config('test.operation','{"kind":"end","endAction":"charity","reason":"Synthetic bulk end"}',true);
select set_config('test.preview',preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array[current_setting('test.first')::uuid],current_setting('test.operation')::jsonb)::text,true);
select is(apply_item_lifecycle_batch(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.operation')::jsonb,current_setting('test.preview')::jsonb)->'items'->0->>'status','applied','staff can end eligible stock directly');
select is((select count(*) from item_events where item_id=current_setting('test.first')::uuid and kind='period_ended'),1::bigint,'one end event');
select throws_like($$select apply_item_lifecycle_batch(current_setting('test.tenant')::uuid,current_setting('test.request')::uuid,'{}',current_setting('test.preview')::jsonb)$$,'%REQUEST_CONFLICT%','receipt cannot be reused by another actor');
reset role;
update tenant_members set role='admin' where tenant_id=current_setting('test.tenant')::uuid and user_id='f0000000-0000-4000-8000-000000000222';
set local role authenticated;
select lives_ok($$select preview_item_lifecycle_batch(current_setting('test.tenant')::uuid,array[current_setting('test.second')::uuid],current_setting('test.operation')::jsonb)$$,'admin can preview direct operations');
select * from finish();
rollback;
